namespace qqworld_collector\module\artificial_intelligence; if (!defined('ABSPATH')) { exit; } class QQWorld_AI_Chat_Manager { private $table_sessions; private $table_messages; private $table_tools; public function __construct() { global $wpdb; $this->table_sessions = $wpdb->prefix . 'qqworld_ai_sessions'; $this->table_messages = $wpdb->prefix . 'qqworld_ai_messages'; $this->table_tools = $wpdb->prefix . 'qqworld_ai_tools'; } public function create_session($model, $provider) { global $wpdb; $uuid = wp_generate_uuid4(); $result = $wpdb->insert( $this->table_sessions, array( 'uuid' => $uuid, 'title' => '新对话', 'model' => sanitize_text_field($model), 'provider' => sanitize_text_field($provider), 'created_at' => current_time('mysql'), 'updated_at' => current_time('mysql'), ), array('%s', '%s', '%s', '%s', '%s', '%s') ); if ($result === false) { return new \WP_Error('db_error', 'Failed to create session'); } return array( 'id' => $wpdb->insert_id, 'uuid' => $uuid, 'title' => '新对话', 'model' => $model, 'provider' => $provider, ); } public function get_session($session_id) { global $wpdb; return $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$this->table_sessions} WHERE id = %d", $session_id ) ); } public function get_session_by_uuid($uuid) { global $wpdb; return $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$this->table_sessions} WHERE uuid = %s", $uuid ) ); } public function get_all_sessions() { global $wpdb; $results = $wpdb->get_results( "SELECT * FROM {$this->table_sessions} ORDER BY updated_at DESC" ); return array_map(function($session) { return (array) $session; }, $results); } public function update_session($session_id, $data) { global $wpdb; $data['updated_at'] = current_time('mysql'); return $wpdb->update( $this->table_sessions, $data, array('id' => $session_id), null, array('%d') ); } public function update_session_title($session_id, $title) { global $wpdb; $title = mb_substr($title, 0, 50); return $wpdb->update( $this->table_sessions, array( 'title' => sanitize_text_field($title), 'updated_at' => current_time('mysql'), ), array('id' => $session_id), array('%s', '%s'), array('%d') ); } public function delete_session($session_id) { global $wpdb; $message_ids = $wpdb->get_col( $wpdb->prepare( "SELECT id FROM {$this->table_messages} WHERE session_id = %d", $session_id ) ); if (!empty($message_ids)) { $placeholders = implode(',', array_fill(0, count($message_ids), '%d')); $wpdb->query( $wpdb->prepare( "DELETE FROM {$this->table_tools} WHERE message_id IN ($placeholders)", $message_ids ) ); } $wpdb->delete( $this->table_messages, array('session_id' => $session_id), array('%d') ); return $wpdb->delete( $this->table_sessions, array('id' => $session_id), array('%d') ); } public function add_message($session_id, $role, $content, $model_used = null, $tokens_used = 0) { global $wpdb; $result = $wpdb->insert( $this->table_messages, array( 'session_id' => $session_id, 'role' => sanitize_text_field($role), 'content' => wp_unslash($content), 'model_used' => sanitize_text_field($model_used), 'tokens_used' => absint($tokens_used), 'created_at' => current_time('mysql'), ), array('%d', '%s', '%s', '%s', '%d', '%s') ); if ($result === false) { return new \WP_Error('db_error', 'Failed to add message'); } $message_id = $wpdb->insert_id; $this->update_session($session_id, array()); return $message_id; } public function get_messages($session_id) { global $wpdb; $results = $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$this->table_messages} WHERE session_id = %d ORDER BY created_at ASC", $session_id ) ); return array_map(function($message) { $msg_array = (array) $message; $tool_calls = $this->get_tool_calls($message->id); if (!empty($tool_calls)) { $msg_array['tool_calls'] = array_map(function($tool_call) { $args = maybe_unserialize($tool_call->tool_args); return array( 'id' => $tool_call->id, 'type' => 'function', 'function' => array( 'name' => $tool_call->tool_name, 'arguments' => is_array($args) ? json_encode($args) : $args, ), ); }, $tool_calls); } return $msg_array; }, $results); } public function get_message($message_id) { global $wpdb; $result = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$this->table_messages} WHERE id = %d", $message_id ), ARRAY_A ); return $result; } public function update_message($message_id, $content, $tokens_used = 0) { global $wpdb; return $wpdb->update( $this->table_messages, array( 'content' => wp_unslash($content), 'tokens_used' => absint($tokens_used), ), array('id' => $message_id), array('%s', '%d'), array('%d') ); } public function delete_message($message_id) { global $wpdb; $wpdb->delete( $this->table_tools, array('message_id' => $message_id), array('%d') ); return $wpdb->delete( $this->table_messages, array('id' => $message_id), array('%d') ); } public function delete_messages_from($session_id, $from_message_id) { global $wpdb; $message_ids = $wpdb->get_col( $wpdb->prepare( "SELECT id FROM {$this->table_messages} WHERE session_id = %d AND id >= %d", $session_id, $from_message_id ) ); if (!empty($message_ids)) { $placeholders = implode(',', array_fill(0, count($message_ids), '%d')); $wpdb->query( $wpdb->prepare( "DELETE FROM {$this->table_tools} WHERE message_id IN ($placeholders)", $message_ids ) ); } return $wpdb->query( $wpdb->prepare( "DELETE FROM {$this->table_messages} WHERE session_id = %d AND id >= %d", $session_id, $from_message_id ) ); } public function add_tool_call($message_id, $tool_name, $tool_args, $tool_result) { global $wpdb; return $wpdb->insert( $this->table_tools, array( 'message_id' => $message_id, 'tool_name' => sanitize_text_field($tool_name), 'tool_args' => maybe_serialize($tool_args), 'tool_result' => maybe_serialize($tool_result), 'created_at' => current_time('mysql'), ), array('%d', '%s', '%s', '%s', '%s') ); } public function get_tool_calls($message_id) { global $wpdb; return $wpdb->get_results( $wpdb->prepare( "SELECT * FROM {$this->table_tools} WHERE message_id = %d ORDER BY created_at ASC", $message_id ) ); } } 